//! Cold start: build the state the scene evaluator starts from (image + heap at the entry of the first frame's evaluator call) WITHOUT a snapshot, by running the original's own
//! start-up and build-script code (0x40168c .. second call of 0x409a50) as statically recompiled Rust (`orig_gen.rs`, generated by re/recomp.py + re/mk_full.py: the complete recursive-descent recompile of the original) on top of the Win32/DirectDraw shim (`win32.rs`).
use crate::scene::*;
use crate::x86rt::Cpu;

pub const IMAGE: &[u8] = include_bytes!("../../re/image.bin");
pub const OEP: u32 = 0x40168c;

/// Run the original from its entry point until the `n`-th call of the scene evaluator 0x409a50 (n = 2: the first real frame); returns the memory at that point and the Cpu.
pub fn build_until_eval(n: u32) -> (Mem, Cpu) { build_with(n, true) }
/// (`full` is kept for the tests' signature; the only translation left is orig_gen, the complete static recompile)
pub fn build_with(n: u32, _full: bool) -> (Mem, Cpu) {
    let mut m = Mem { img: IMAGE.to_vec(), heap: vec![0; 0x100_0000], stk: vec![0; STACK_LEN], log: None };
    if let Some((w, h)) = crate::custom_size() { m.w32(0x410033, w as u32 | (h as u32) << 16); }   // entry 3 of the resolution list (4 bytes: w, h as u16)
    let mut c = Cpu::new();
    c.r[4] = 0x00ff_ff00; m.w32(c.r[4], 0x7f00_0040);       // return address -> ExitProcess stub, like the harness
    c.stop_pc = 0x409a50; c.stop_n = n;
    if std::env::var("H7TRACE").is_ok() { c.trace = Some(vec![]); }
    let r = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| crate::orig_gen::run(&mut c, &mut m, OEP)));
    if r.is_err() { if let Some(t) = &c.trace { let n = t.len(); eprintln!("last pcs: {:x?}", &t[n.saturating_sub(40)..]); eprintln!("regs {:x?} esp {:x}", c.r, c.r[4]); } std::panic::resume_unwind(r.unwrap_err()); }
    if crate::full() { let ebp = m.r32(0x42a3f8); m.w32(ebp + 0x58, 0); }   // [ebp+0x58] = the original's quality level (2 = lowest): 0 subdivides every mixed block down to single pixels
    let used = (c.w.heap_end - HEAP_BASE) as usize; m.heap.truncate(used.max(1));
    (m, c)
}

/// One frame of the demo at time `t` (1/2048 s units) by running the ORIGINAL code (complete static recompile, orig_gen.rs) from the cold state: the evaluator 0x409a50, which draws and presents
/// into the framebuffer the Lock shim handed out. Returns the 320x240 frame as BGRX bytes.
pub fn frame_orig(cold: &(Mem, Cpu), t: i32) -> Vec<u8> {
    let (mut m, mut c) = (cold.0.clone(), cold.1.clone());
    c.stop_pc = u32::MAX; c.r[3] = t as u32; c.push(&mut m, 0xdead_0000);
    if std::env::var("H7TRACE").is_ok() { c.trace = Some(vec![]); }
    let r = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| crate::orig_gen::run(&mut c, &mut m, 0x409a50)));
    if let Err(e) = r { if let Some(t) = &c.trace { let n = t.len(); eprintln!("last pcs: {:x?}\nregs {:x?}", &t[n.saturating_sub(12)..], c.r); } std::panic::resume_unwind(e); }
    m.bytes(c.w.fb_buf, ({ let (w, h) = crate::native_size(); w * h * 4 }) as usize).to_vec()
}

/// Sequential player: the scene is NOT a pure function of t (rotating objects accumulate a matrix product per frame: classes 0x4097ce / 0x40b5a4 / 0x40b603 use dt = t - last t), so the exact frame at a grid time k needs
/// the evaluations of all earlier grid frames, exactly like the original run at a fixed frame step (the emulator harness: `step_ms` per presented frame, frame 1 at t = 0).
pub struct Player { pub m: Mem, pub c: Cpu, pub step_us: u32, /** number of frames presented so far (frame 1 is the first) */ pub k: u32 }
impl Player {
    pub fn new(step_ms: u32) -> Player { Player::new_us(step_ms * 1000) }
    /// frame step in microseconds (HQ renders at e.g. 16667 us = 60 fps; not bit-exact against the 40 ms emulator run)
    pub fn new_us(step_us: u32) -> Player { let (m, c) = build_until_eval(2); Player { m, c, step_us, k: 0 } }
    /// demo time (1/2048 s) of frame k >= 1: the main loop computes clock * 0x800 / 0x1234dc with clock = timeGetTime * 0x4a9 (ms of the virtual clock, +step per present)
    pub fn t_of(&self, k: u32) -> i32 { ((((k - 1) as u64 * self.step_us as u64 * 0x4a9 / 1000) * 0x800) / 0x1234dc) as i32 }
    /// evaluate + draw + present the next frame; returns the 320x240 BGRX bytes
    pub fn step(&mut self) -> Vec<u8> {
        self.k += 1; let t = self.t_of(self.k);
        self.c.stop_pc = u32::MAX; self.c.r[3] = t as u32; self.c.push(&mut self.m, 0xdead_0000);
        crate::orig_gen::run(&mut self.c, &mut self.m, 0x409a50);
        self.m.bytes(self.c.w.fb_buf, { let (w, h) = crate::native_size(); w * h * 4 }).to_vec()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    /// differential: the cold-built state at the first evaluator call of the first frame vs the emulator snapshot (image + heap)
    #[test] fn cold_state_matches_snapshot() {
        let full = true;
        let Some(snap) = crate::scene::tests::load("snap1") else { eprintln!("no snapshot"); return; };
        let t0 = std::time::Instant::now();
        let (m, c) = build_with(2, full);
        eprintln!("cold build {:?}, heap {:#x}, presents {}", t0.elapsed(), m.heap.len(), c.w.presents);
        let mut bad = vec![];
        let n = m.img.len().min(snap.img.len());
        // 0x42a408..0x42a474 = the FSAVE area of the image sampler 0x40d4b1 (scratch: written by fsave, read back by frstor right after; stale x87 register bytes are not modelled)
        for i in 0..n { let a = IMG_BASE + i as u32; if m.img[i] != snap.img[i] && !(0x42a408..0x42a474).contains(&a) { bad.push(a); } }
        eprintln!("image differing bytes: {}", bad.len());
        let ni = bad.len();
        for i in 0..m.heap.len().min(snap.heap.len()) { if m.heap[i] != snap.heap[i] { bad.push(HEAP_BASE + i as u32); } }
        eprintln!("heap differing bytes: {} (len {:#x} vs {:#x})", bad.len() - ni, m.heap.len(), snap.heap.len());
        for a in bad.iter().take(60) { eprintln!("  {a:#x}: {:#x} vs {:#x}", m.r8(*a), snap.r8(*a)); }
        assert!(bad.is_empty());
    }
}

#[cfg(test)]
mod frames {
    use super::*;
    fn mae(a: &[u8], b: &[u8]) -> f64 { let (mut s, mut n) = (0.0, 0.0); for (i, (x, y)) in a.iter().zip(b).enumerate() { if i % 4 != 3 { s += (*x as f64 - *y as f64).abs(); n += 1.0; } } s / n }
    /// full frames from the COLD state (no snapshot) vs the emulator's presented frames
    #[test] fn cold_frames_match_the_emulator() {
        let (cold, _) = build_until_eval(2);
        let mut n = 0;
        for (k, t) in crate::scene::tests::times() {
            if k == 0 { continue; }      // frame 0 is the 'please wait' frame presented during the build
            let Ok(fb) = std::fs::read(format!("{}/fb{k}.bin", crate::scene::tests::dir())) else { continue };
            let mut s = Scene::new(cold.clone()); s.frame(t);
            let f = crate::present(&s); let bgra: Vec<u8> = f.rgba.chunks(4).flat_map(|p| [p[2], p[1], p[0], 0]).collect();
            let e = mae(&bgra, &fb); eprintln!("cold frame {k} (t={t}): mean abs error {e:.4}, skipped {:?}", s.skipped);
            assert_eq!(e, 0.0); n += 1;
        }
        assert!(n >= 5);
    }
}

#[cfg(test)]
mod orig_frames {
    use super::*;
    /// frames of the ORIGINAL code (orig_gen) from the cold state vs the emulator's presented frames (H7FRAMES=k1,k2,.. of the snapshot directory's fb<k>.bin / times.txt)
    #[test] fn orig_frames_match() {
        let cold = build_with(2, true);
        let times = crate::scene::tests::times();
        let want: Vec<u32> = match std::env::var("H7FRAMES") { Ok(s) if s == "all" => times.iter().map(|x| x.0).filter(|k| *k >= 1).collect(), Ok(s) => s.split(',').map(|x| x.parse().unwrap()).collect(), Err(_) => vec![1, 2, 31, 60, 100, 240] };
        if std::env::var("H7LOC").is_err() { std::panic::set_hook(Box::new(|_| {})); }
        let mut bad = vec![];
        for k in want {
            let Some(t) = times.iter().find(|x| x.0 == k).map(|x| x.1) else { continue };
            let Ok(fb) = std::fs::read(format!("{}/fb{k}.bin", crate::scene::tests::dir())) else { continue };
            let t0 = std::time::Instant::now();
            match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| frame_orig(&cold, t))) {
                Ok(f) => { if let Ok(dd) = std::env::var("H7DUMP") { std::fs::write(format!("{dd}/got{k}.bin"), &f).unwrap(); }
                let d = f.iter().zip(&fb).enumerate().filter(|(i, (a, b))| i % 4 != 3 && a != b).count(); eprintln!("orig frame {k} (t={t}): {d} differing bytes, {:?}", t0.elapsed()); if d != 0 { if d < 100 { let v: Vec<_> = f.iter().zip(&fb).enumerate().filter(|(i, (a, b))| i % 4 != 3 && a != b).map(|(i, (a, b))| (i / 4 % 320, i / 4 / 320, i % 4, *a, *b)).collect(); eprintln!("  diffs (x,y,chan,got,want): {v:?}"); } bad.push((k, format!("{d} bytes"))); } }
                Err(e) => { let msg = e.downcast_ref::<String>().cloned().or(e.downcast_ref::<&str>().map(|s| s.to_string())).unwrap_or_default(); eprintln!("orig frame {k} (t={t}): PANIC {msg}"); bad.push((k, msg)); }
            }
        }
        assert!(bad.is_empty(), "{} frames differ: {:?}", bad.len(), &bad[..bad.len().min(10)]);
    }
}

#[cfg(test)]
mod player {
    use super::*;
    /// H7STEP_MS=<ms> H7SNAP_DIR=<dir of fb<k>.bin>: step the Player over every frame and compare with the emulator's presented frame k (frames missing in the directory are only stepped)
    #[test] fn player_matches_the_emulator() {
        let step: u32 = std::env::var("H7STEP_MS").ok().and_then(|s| s.parse().ok()).unwrap_or(40);
        let maxk: u32 = std::env::var("H7MAXK").ok().and_then(|s| s.parse().ok()).unwrap_or(250);
        let mut p = Player::new(step); let dir = crate::scene::tests::dir();
        let (mut ok, mut bad, mut first_bad) = (0, 0, 0);
        while p.k < maxk {
            let f = p.step(); let k = p.k;
            let Ok(fb) = std::fs::read(format!("{dir}/fb{k}.bin")) else { continue };
            let d = f.iter().zip(&fb).enumerate().filter(|(i, (a, b))| i % 4 != 3 && a != b).count();
            if d == 0 { ok += 1; } else { bad += 1; if first_bad == 0 { first_bad = k; } eprintln!("frame {k} (t={}): {d} differing bytes", p.t_of(k)); }
        }
        eprintln!("player: {ok} frames exact, {bad} differ (first {first_bad})");
        assert_eq!(bad, 0);
    }
}

#[cfg(test)]
mod sweep {
    use super::*;
    /// H7SWEEP=start,end,step (seconds): run Scene::frame over the demo from the cold state and report panics ("never executed" raster addresses etc.)
    #[test] #[ignore] fn sweep() {
        let spec = std::env::var("H7SWEEP").unwrap_or("0,300,1".into()); let v: Vec<f64> = spec.split(',').map(|x| x.parse().unwrap()).collect();
        let (cold, _) = build_until_eval(2);
        std::panic::set_hook(Box::new(|_| {}));
        let mut t = v[0];
        while t <= v[1] {
            let ticks = (t * 2048.0) as i32;
            let r = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| { let mut s = Scene::new(cold.clone()); let t0 = std::time::Instant::now(); s.frame(ticks); (t0.elapsed(), s.skipped.clone()) }));
            match r { Ok((d, sk)) => println!("t={t} ok {d:?} skipped {sk:x?}"), Err(e) => { let msg = e.downcast_ref::<String>().cloned().or(e.downcast_ref::<&str>().map(|s| s.to_string())).unwrap_or_default(); println!("t={t} PANIC {msg}"); } }
            t += v[2];
        }
    }
}

#[cfg(test)]
mod inventory {
    use super::*;
    use std::collections::BTreeMap;
    /// every distinct eval handler [+0x10] / draw handler [+0x30] / parameter apply handler of the node tree that the cold build created
    #[test] #[ignore] fn handlers() {
        let (m, _) = build_until_eval(2); let ebp = m.r32(0x42a3f8);
        let mut ev: BTreeMap<u32, u32> = BTreeMap::new(); let mut dr: BTreeMap<u32, u32> = BTreeMap::new(); let mut pa: BTreeMap<u32, u32> = BTreeMap::new();
        let root = m.r32(ebp + 0x50); let mut stack = vec![root, m.r32(root + 0x18)];
        while let Some(n) = stack.pop() {
            if n == 0 { continue; }
            *ev.entry(m.r32(n + 0x10)).or_default() += 1; *dr.entry(m.r32(n + 0x30)).or_default() += 1;
            let mut p = m.r32(n + 0x14); while p != 0 { *pa.entry(m.r32(p + 0x10)).or_default() += 1; p = m.r32(p + 8); }
            stack.push(m.r32(n + 4)); stack.push(m.r32(n + 8));
            if m.r32(n + 0x30) == 0x40a680 { stack.push(m.r32(n + 0x3c)); }
        }
        println!("eval {ev:x?}\ndraw {dr:x?}\nparam apply {pa:x?}");
    }
}

#[cfg(test)]
mod diff3d {
    use super::*;
    /// H7PS=<psnap.bin> H7T=<t> H7OUT=<file>: run the original's 3D draw 0x40a680 (orig_gen) on the snapshot like re/diff3d.py does in Unicorn; dump image ++ heap
    #[test] #[ignore] fn diff3d() {
        let (Ok(p), Ok(t), Ok(out)) = (std::env::var("H7PS"), std::env::var("H7T"), std::env::var("H7OUT")) else { return };
        let mut m = Mem::from_snapshot(&std::fs::read(p).unwrap(), crate::scene::tests::IMG_LEN); let t: u32 = t.parse().unwrap();
        let ebp = m.r32(0x42a3f8); let root = m.r32(ebp + 0x50); let vp = m.r32(root + 0x18);
        fn walk(m: &Mem, mut n: u32, out: &mut Vec<u32>) { while n != 0 { if m.r32(n + 0x30) == 0x40a680 && m.r8(n) != 0 { out.push(n); } let c = m.r32(n + 8); if c != 0 { walk(m, c, out); } n = m.r32(n + 4); } }
        let mut v = vec![]; walk(&m, vp, &mut v); let nd = v[0];
        let mut c = Cpu::new(); c.r[4] = 0xfff000; m.w32(c.r[4], 0xdead_0000);
        c.r[3] = t; c.r[6] = nd; c.r[7] = vp; c.r[5] = ebp; c.stop_pc = u32::MAX;
        let mut entry = 0x40a680;
        if std::env::var("H7MODE").as_deref() == Ok("frame") {      // the whole frame incl. the present, with the Win32 shim state of the cold build
            let (_, cc) = build_with(2, true); c = cc; c.r[4] = 0xffff00; m.w32(c.r[4], 0xdead_0000); c.r[3] = t; c.stop_pc = u32::MAX; entry = 0x409a50; eprintln!("fb_buf {:#x}", c.w.fb_buf);
        }
        if std::env::var("H7TRACE").is_ok() { c.trace = Some(vec![]); }
        crate::orig_gen::run(&mut c, &mut m, entry);
        let mut o = m.img.clone(); o.extend_from_slice(&m.heap); std::fs::write(out, o).unwrap();
    }
}
